function validate([nums]) {
  if (!Array.isArray(nums) || nums.length < 1) return 'nums needs at least one value.';
  if (nums.some(v => !Number.isInteger(v) || v < 1 || v > 1e9)) return 'Each value is a whole number from 1 to 10^9.';
  if (nums.reduce((total, v) => total + v, 0) > 1e15) return 'The values add up to at most 10^15.';
  const finished = new Set();
  for (let i = 1; i < nums.length; i++) {
    if (nums[i] === nums[i - 1]) continue;
    finished.add(nums[i - 1]);
    if (finished.has(nums[i])) return 'Equal values must be next to each other: ' + nums[i] + ' appears in two separate places.';
  }
  return null;
}

