function adapt(input, solve, kit) {
  const [values] = input;
  class BigArray {
    constructor(elements) {
      this.elements = elements.slice();
    }
    at(index) {
      if (!Number.isInteger(index) || index < 0 || index >= this.elements.length) throw new Error(`at(${index}) needs a whole-number index from 0 to ${this.elements.length - 1}.`);
      return this.elements[index];
    }
    size() {
      return this.elements.length;
    }
  }
  const result = solve(new BigArray(values));
  if (!Number.isInteger(result)) throw new Error('Return the number of blocks as a whole number.');
  return result;
}

