function countBlocks(nums) {
  const n = nums.size();
  let blocks = 0;
  let start = 0;

  while (start < n) {
    const value = nums.at(start);
    let low = start;
    let high = n - 1;
    while (low < high) {
      const mid = low + Math.ceil((high - low) / 2);
      if (nums.at(mid) === value) {
        low = mid;
      } else {
        high = mid - 1;
      }
    }
    blocks++;
    start = low + 1;
  }
  return blocks;
}

