function countBlocks(nums) {
  // Read every element and count the places where a new value begins.
  let count = 0;
  for (let i = 0; i < nums.size(); i++) {
    if (i === 0 || nums.at(i) !== nums.at(i - 1)) count += 1;
  }
  return count;
}

