function generate(rand, size) {
  const pick = k => Math.floor(rand() * k);
  const total = size === 'large' ? 1000 + pick(1001) : 1 + pick(14);
  // Choose how many blocks, then cut the length into that many non-empty runs.
  const shape = rand();
  const count = shape < 0.2 ? 1 : shape < 0.4 ? total : 1 + pick(size === 'large' ? 80 : total);
  const cuts = new Set();
  while (cuts.size < count - 1) cuts.add(1 + pick(total - 1));
  const bounds = [0, ...[...cuts].sort((a, b) => a - b), total];
  const used = new Set();
  const nums = [];
  for (let b = 0; b + 1 < bounds.length; b++) {
    let value;
    do value = size === 'large' ? 1 + pick(1000000000) : 1 + pick(30); while (used.has(value));
    used.add(value);
    for (let i = bounds[b]; i < bounds[b + 1]; i++) nums.push(value);
  }
  return [nums];
}
